const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
const {loadCatalog}=require('./knowledge-catalog.cjs');
const {FORMAT}=require('./action-state.cjs');
let dir,app,author,reader,state,actionRevision,pathRevision,owner;
beforeEach(async()=>{dir=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-path-service-'));app=createAuthenticatedActionApp({dataDir:dir,reviewDirectory:path.join(dir,'assets'),rateLimitEnabled:false}).app;author=request.agent(app);reader=request.agent(app);owner=(await author.post('/api/register').send({name:'路径作者',password:'test-only-2026'})).body.user.id;await reader.post('/api/register').send({name:'路径读者',password:'test-only-2026'});state={schema:1,mode:'local-simulation',events:[],activeId:null,habits:[{id:'h',name:'阅读',formedAt:null}],habitId:'h',templates:{},nodes:loadCatalog().nodes.map(n=>({...n,id:n.originId,version:n.sourceVersion,methods:[]})),lights:[],paths:[{id:'mine',title:'从运算到检验',nodes:['num','calc','eq','num'],visibility:'private',bookmarked:true}]};actionRevision=(await author.get('/api/action-state')).body.revision;await saveSource();pathRevision=(await author.get('/api/review-path-publications')).body.revision});
afterEach(()=>{if(!path.resolve(dir).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected path fixture');fs.rmSync(dir,{recursive:true,force:true})});
async function saveSource(){const r=await author.put('/api/action-state').set('If-Match',actionRevision).send({format:FORMAT,data:state});expect(r.status).toBe(200);actionRevision=r.body.revision}
function publish(action='publish',headers={}){return author.post('/api/review-path-publications').set({'If-Match':actionRevision,'If-Path-Match':pathRevision,...headers}).send({pathId:'mine',action,consent:true})}
it('publishes an exact ordered path without exposing bookmarks or copying another owner progress and retains all revisions in export',async()=>{let r=await publish();expect(r.status).toBe(200);pathRevision=r.body.revision;const pub=(await reader.get('/api/review-public-paths')).body;expect(pub.total).toBe(1);expect(pub.paths[0].targets.map(t=>t.originId)).toEqual(['num','calc','eq','num']);expect(pub.paths[0]).not.toHaveProperty('sourceId');expect(pub.paths[0]).not.toHaveProperty('bookmarked');expect(pub.paths[0].targets[0].ownership).toBe('group');state.paths[0].title='修订后的检验路径';state.paths[0].nodes=['eq','num'];await saveSource();r=await publish();expect(r.status).toBe(200);expect(r.body.entry.versions).toHaveLength(2);expect(r.body.entry.versions[0].targets).toHaveLength(4);const archive=(await author.get('/api/review-account-export')).body;expect(archive.service.pathPublications.entries[0].versions).toHaveLength(2);expect((await reader.get('/api/review-path-publications')).body.store.entries).toHaveLength(0)});
it('requires explicit consent, source and path revisions while keeping an identical lost-ack retry idempotent',async()=>{expect((await author.post('/api/review-path-publications').send({pathId:'mine',action:'publish',consent:false})).status).toBe(403);expect((await publish('publish',{'If-Match':'stale'})).status).toBe(409);expect((await publish('publish',{'If-Path-Match':'stale'})).status).toBe(409);const saved=await publish();expect(saved.status).toBe(200);const retried=await publish();expect(retried.body.entry).toEqual(saved.body.entry);state.paths[0].title='新内容';await saveSource();expect((await publish()).status).toBe(409);expect((await reader.get('/api/review-public-paths')).body.paths[0].title).toBe('从运算到检验')});
it('withdraws independently of a deleted local source and keeps original history private',async()=>{const saved=await publish();pathRevision=saved.body.revision;state.paths=[];await saveSource();expect((await publish('withdraw')).status).toBe(200);expect((await reader.get('/api/review-public-paths')).body.total).toBe(0);expect((await author.get('/api/review-path-publications')).body.store.entries[0].versions).toHaveLength(1);expect((await reader.post('/api/review-path-publications').set('If-Path-Match',(await reader.get('/api/review-path-publications')).body.revision).send({pathId:'mine',action:'withdraw',consent:true})).status).toBe(404)});
it('blocks private targets instead of silently publishing them and accepts an explicitly shared personal definition without changing its ownership',async()=>{const n={id:'personal',title:'画草图',goal:'解释草图的构图关系',five:'画三条线',domain:'实践',branch:'草图',ownership:'personal',visibility:'private',version:1,methods:[]};state.nodes.push(n);state.paths[0].nodes=['personal'];await saveSource();expect((await publish()).status).toBe(409);expect((await reader.get('/api/review-public-paths')).body.total).toBe(0);expect((await author.post('/api/review-private-targets').set('If-Match',actionRevision).send({nodeId:n.id,sourceVersion:1})).status).toBe(201);expect((await author.post('/api/review-target-sharing').set('If-Match',actionRevision).send({nodeId:n.id,sourceVersion:1,action:'publish',consent:true})).status).toBe(201);const published=await publish();expect(published.status).toBe(200);const visible=(await reader.get('/api/review-public-paths')).body.paths[0];expect(visible.targets[0].ownership).toBe('personal');expect(visible.targets[0].ownerId).toBe(owner);expect((await author.post('/api/review-target-sharing').set('If-Match',actionRevision).set('If-Target-Match',(await author.get('/api/review-target-sharing').query({nodeId:n.id})).body.revision).send({nodeId:n.id,sourceVersion:1,action:'withdraw',consent:true})).status).toBe(200);expect((await reader.get('/api/review-public-paths')).body.total).toBe(0)});
it('guards authentication, actor, Origin, seeds and search parameters and preserves unreadable history',async()=>{expect((await request(app).get('/api/review-public-paths')).status).toBe(401);expect((await reader.get('/api/review-path-publications').set('X-Action-Account',owner)).status).toBe(409);expect((await reader.get('/api/review-public-paths').set('Origin','https://unauthorized.example')).status).toBe(403);state.paths[0].seed=true;await saveSource();expect((await publish()).status).toBe(409);state.paths[0].seed=false;await saveSource();expect((await publish()).status).toBe(200);const file=path.join(dir,'path-publications',owner+'.json');fs.writeFileSync(file,'{PRIVATE-BROKEN');expect((await author.get('/api/review-path-publications')).status).toBe(503);expect((await reader.get('/api/review-public-paths')).status).toBe(503);expect((await author.get('/api/review-account-export')).status).toBe(500);expect(fs.readFileSync(file,'utf8')).toBe('{PRIVATE-BROKEN')});

it('finds a public path by a goal or starting action and removes it from search after withdrawal',async()=>{
 const saved=await publish();
 expect(saved.status).toBe(200);
 pathRevision=saved.body.revision;
 const target=saved.body.entry.versions[0].targets.find(t=>t.originId==='eq');
 const route='/api/review-public-paths';
 for(const query of [target.goal,target.five,target.five+'　'+saved.body.entry.authorName]){
  expect(query).toBeTruthy();
  const result=await reader.get(route).query({query,authorId:owner});
  expect(result.status).toBe(200);
  expect(result.body.paths.map(p=>p.id)).toEqual([saved.body.entry.id]);
 }
 expect((await publish('withdraw')).status).toBe(200);
 const withdrawn=await reader.get(route).query({query:target.goal,authorId:owner});
 expect(withdrawn.status).toBe(200);
 expect(withdrawn.body.paths).toEqual([]);
});
it('scopes public path cursors to the reader and matching publications',async()=>{
 const first=await publish();
 pathRevision=first.body.revision;
 state.paths.push({id:'second',title:'Second public path',nodes:['eq'],visibility:'private'});
 await saveSource();
 const second=await author.post('/api/review-path-publications').set({'If-Match':actionRevision,'If-Path-Match':pathRevision}).send({pathId:'second',action:'publish',consent:true});
 expect(second.status).toBe(200);
 pathRevision=second.body.revision;
 const route='/api/review-public-paths',filter={authorId:owner,limit:1};
 const a=(await reader.get(route).query(filter)).body;
 expect(a.total).toBe(2);
 expect(a.nextCursor).toBeTruthy();
 const next={...filter,cursor:a.nextCursor};
 const other=request.agent(app);
 expect((await other.post('/api/register').send({name:'另一位路径作者',password:'test-only-2026'})).status).toBe(201);
 const otherState=(await other.get('/api/action-state')).body;
 const saved=await other.put('/api/action-state').set('If-Match',otherState.revision).send({format:FORMAT,data:state});
 expect(saved.status).toBe(200);
 const otherPlan=(await other.get('/api/review-path-publications')).body;
 expect((await other.post('/api/review-path-publications').set({'If-Match':saved.body.revision,'If-Path-Match':otherPlan.revision}).send({pathId:'mine',action:'publish',consent:true})).status).toBe(200);
 expect((await other.get(route).query(next)).status).toBe(409);
 const b=await reader.get(route).query(next);
 expect(b.status).toBe(200);
 expect(b.body.paths[0].id).not.toBe(a.paths[0].id);
 expect(b.body.paths[0]).not.toHaveProperty('versions');
 expect((await reader.get(route).query({...filter,query:'Second'})).body.total).toBe(1);
 expect((await publish('withdraw')).status).toBe(200);
 const stale=await reader.get(route).query(next);
 expect(stale.status).toBe(409);
 expect(stale.body.code).toBe('PATH_CURSOR_CHANGED');
 expect((await reader.get(route).query(filter)).body.total).toBe(1);
 for(const args of [{query:['a','b']},{limit:0},{limit:51},{query:'x'.repeat(121)}])expect((await reader.get(route).query(args)).status).toBe(400);
});
it('retains a new publication occurrence when identical content is deliberately published again after withdrawal',async()=>{let r=await publish();const first=r.body.entry.versions[0];pathRevision=r.body.revision;r=await publish('withdraw');pathRevision=r.body.revision;r=await publish();expect(r.status).toBe(200);expect(r.body.entry.versions).toHaveLength(2);expect(r.body.entry.versions[0]).toEqual(first);expect(r.body.entry.versions[1].version).toBe(first.version);pathRevision=r.body.revision;expect((await publish()).body.entry.versions).toHaveLength(2)});

it('validates saved path bookmark fingerprints and keeps the prior source when an imported snapshot is altered',async()=>{await publish();const p=(await reader.get('/api/review-public-paths')).body.paths[0];state.settings={publicPathBookmarks:[p]};await saveSource();const bad=JSON.parse(JSON.stringify(state));bad.settings.publicPathBookmarks[0].targets[0].goal='Tampered saved goal';expect((await author.put('/api/action-state').set('If-Match',actionRevision).send({format:FORMAT,data:bad})).status).toBe(400);expect((await author.get('/api/action-state')).body.state.data.settings.publicPathBookmarks[0]).toEqual(p);expect((await reader.get('/api/review-public-paths/one').query({id:p.id})).body.path).toEqual(p);expect((await reader.get('/api/review-public-paths/one').query({id:['a','b']})).status).toBe(400);pathRevision=(await author.get('/api/review-path-publications')).body.revision;await publish('withdraw');expect((await reader.get('/api/review-public-paths/one').query({id:p.id})).status).toBe(404)});

it('publishes a rearranged reader copy with verified source attribution without claiming its nodes or progress',async()=>{await publish();const parent=(await reader.get('/api/review-public-paths')).body.paths[0],copy=JSON.parse(JSON.stringify(state));copy.paths=[{id:'reader-copy',title:'Reader rearrangement',nodes:[],visibility:'private',sourcePathSnapshot:parent,targetRefs:parent.targets.slice().reverse().map(target=>({kind:'public',target}))}];copy.lights=[];const initial=(await reader.get('/api/action-state')).body,saved=await reader.put('/api/action-state').set('If-Match',initial.revision).send({format:FORMAT,data:copy});expect(saved.status).toBe(200);const plan=(await reader.get('/api/review-path-publications')).body,result=await reader.post('/api/review-path-publications').set({'If-Match':saved.body.revision,'If-Path-Match':plan.revision}).send({pathId:'reader-copy',action:'publish',consent:true});expect(result.status).toBe(200);const paths=(await author.get('/api/review-public-paths')).body.paths,child=paths.find(p=>p.id===result.body.entry.id);expect(child.targets.map(t=>t.originId)).toEqual(['num','eq','calc','num']);expect(child.sourcePath).toEqual({id:parent.id,version:parent.version,authorId:parent.authorId,authorName:parent.authorName,title:parent.title});expect(child.authorId).not.toBe(parent.authorId);expect(child.targets.every(t=>t.ownership==='group'&&t.ownerId===null)).toBe(true);require('./path-bookmark-schema.cjs').validatePathBookmarks([child]);expect((await author.get('/api/review-public-paths/target').query({treeId:child.targets[0].treeId,nodeId:child.targets[0].nodeId})).body.target).toEqual(child.targets[0]);const archive=(await reader.get('/api/review-account-export')).body;expect(archive.service.actionState.data.paths[0].sourcePathSnapshot).toEqual(parent)});

it('rejects forged copy attribution and unavailable source publication without changing the saved private copy',async()=>{await publish();const parent=(await reader.get('/api/review-public-paths')).body.paths[0],copy=JSON.parse(JSON.stringify(state));copy.paths=[{id:'reader-copy',title:'Private copy',nodes:[],visibility:'private',sourcePathSnapshot:{...parent,authorName:'Forged author'},targetRefs:parent.targets.map(target=>({kind:'public',target}))}];let initial=(await reader.get('/api/action-state')).body,saved=await reader.put('/api/action-state').set('If-Match',initial.revision).send({format:FORMAT,data:copy});expect(saved.status).toBe(200);const plan=(await reader.get('/api/review-path-publications')).body;const send=revision=>reader.post('/api/review-path-publications').set({'If-Match':revision,'If-Path-Match':plan.revision}).send({pathId:'reader-copy',action:'publish',consent:true});expect((await send(saved.body.revision)).status).toBe(409);expect((await reader.get('/api/review-path-publications')).body.store.entries).toHaveLength(0);copy.paths[0].sourcePathSnapshot=parent;saved=await reader.put('/api/action-state').set('If-Match',saved.body.revision).send({format:FORMAT,data:copy});expect(saved.status).toBe(200);pathRevision=(await author.get('/api/review-path-publications')).body.revision;await publish('withdraw');expect((await send(saved.body.revision)).status).toBe(409);expect((await reader.get('/api/action-state')).body.state.data.paths[0].sourcePathSnapshot).toEqual(parent);expect((await request(app).get('/api/review-public-paths/target').query({treeId:parent.targets[0].treeId,nodeId:parent.targets[0].nodeId})).status).toBe(401)});

it('discovers a path-only author with public profile fields and filters exact author path scopes',async()=>{await publish();const profile=path.join(dir,'profiles.json');fs.writeFileSync(profile,JSON.stringify([{id:owner,visibility:'private',tagline:'PRIVATE-TAG',about:'PRIVATE-ABOUT',focus:'PRIVATE-FOCUS'}]));let view=await reader.get('/api/review-public-tutorials/author').query({id:owner});expect(view.status).toBe(200);expect(view.body.total).toBe(0);expect(view.body.author.profile).toBeNull();fs.writeFileSync(profile,JSON.stringify([{id:owner,visibility:'public',tagline:'Public path author',about:'My sequence',focus:'Algebra',secret:'PRIVATE-SECRET'}]));view=await reader.get('/api/review-public-tutorials/author').query({id:owner});expect(view.body.author.profile.tagline).toBe('Public path author');expect(JSON.stringify(view.body)).not.toContain('PRIVATE-');pathRevision=(await author.get('/api/review-path-publications')).body.revision;state.paths.push({id:'second',title:'Another path',nodes:['eq'],visibility:'private'});await saveSource();const extra=await author.post('/api/review-path-publications').set({'If-Match':actionRevision,'If-Path-Match':pathRevision}).send({pathId:'second',action:'publish',consent:true});expect(extra.status).toBe(200);const peerState=JSON.parse(JSON.stringify(state));peerState.paths=[{id:'other-author',title:'Path mentions '+view.body.author.name,nodes:['eq'],visibility:'private'}];const peerInitial=(await reader.get('/api/action-state')).body,peerSaved=await reader.put('/api/action-state').set('If-Match',peerInitial.revision).send({format:FORMAT,data:peerState});expect(peerSaved.status).toBe(200);const peerPlan=(await reader.get('/api/review-path-publications')).body;expect((await reader.post('/api/review-path-publications').set({'If-Match':peerSaved.body.revision,'If-Path-Match':peerPlan.revision}).send({pathId:'other-author',action:'publish',consent:true})).status).toBe(200);const all=(await reader.get('/api/review-public-paths').query({limit:1})).body,scoped=(await reader.get('/api/review-public-paths').query({authorId:owner,limit:1})).body;expect(all.total).toBe(3);expect(scoped.authorId).toBe(owner);expect(scoped.total).toBe(2);expect(scoped.paths.every(p=>p.authorId===owner)).toBe(true);expect((await reader.get('/api/review-public-paths').query({authorId:owner,limit:1,cursor:all.nextCursor})).status).toBe(409);expect((await reader.get('/api/review-public-paths').query({authorId:owner,limit:1,cursor:scoped.nextCursor})).body.paths).toHaveLength(1);expect((await reader.get('/api/review-public-paths').query({authorId:owner,query:'Missing'})).body.total).toBe(0);for(const authorId of [['a','b'],'../owner','x'.repeat(65)])expect((await reader.get('/api/review-public-paths').query({authorId})).status).toBe(400);pathRevision=extra.body.revision;await publish('withdraw');const current=(await author.get('/api/review-path-publications')).body;await author.post('/api/review-path-publications').set('If-Path-Match',current.revision).send({pathId:'second',action:'withdraw',consent:true});expect((await reader.get('/api/review-public-tutorials/author').query({id:owner})).status).toBe(404)});
